map.addEventListener('pointerup',endPointer);
map.addEventListener('pointercancel',endPointer);
map.addEventListener('pointerleave',e=>{if(!panning&&e.pointerType==='mouse'){hover=null;hideTip();}});
// Wheel zoom, normalized across devices: trackpads fire many small pixel-mode
// deltas while mouse wheels fire few large line-mode ones — a fixed per-event
// multiplier made trackpads zoom explosively. Scale exponentially by the
// actual normalized delta instead (~15% per 100px wheel notch), keeping the
// old feel for a mouse wheel while taming high-frequency trackpad streams.
map.addEventListener('wheel',e=>{e.preventDefault();
  const px=e.deltaMode===1?e.deltaY*16:e.deltaMode===2?e.deltaY*100:e.deltaY;
  zoomAbout(e.offsetX,e.offsetY,view.scale*Math.exp(-px*0.0015));
},{passive:false});
// Keep the double-clicked point fixed on screen while doubling the zoom
// (centering on the point instead made the view jump mid-ease).
map.addEventListener('dblclick',e=>{zoomAbout(e.offsetX,e.offsetY,view.scale*2);});
// Keyboard map control (the canvas is tabbable): arrows pan, +/- zoom, 0 fits.
map.addEventListener('keydown',e=>{
  const panDeg=60*DPR/pxPerDeg(); // ~60 CSS px per keypress at the current zoom
  if(e.key==='ArrowLeft')target.cx-=panDeg;
  else if(e.key==='ArrowRight')target.cx+=panDeg;
  else if(e.key==='ArrowUp')target.cy+=panDeg;
  else if(e.key==='ArrowDown')target.cy-=panDeg;
  else if(e.key==='+'||e.key==='=')target.scale=Math.min(80,target.scale*1.6);
  else if(e.key==='-'||e.key==='_')target.scale=Math.max(0.8,target.scale/1.6);
  else if(e.key==='0')fitView();
  else return;
  e.preventDefault();
});
// Single deselection path (empty-map click, Escape, fit): show the whole
// flow network again and reset the inspector.
function clearSelection(){selected=null;hover=null;renderInspectorEmpty();syncHash(true);}
function fitView(){target={cx:10,cy:25,scale:1};clearSelection();}
document.getElementById('zin').onclick=()=>target.scale=Math.min(80,target.scale*1.6);
document.getElementById('zout').onclick=()=>target.scale=Math.max(0.8,target.scale/1.6);
/* Flow budget control. The map draws the biggest N relationships by default;
   this is how you ask for more of the tail. */
function syncFlowTop(){
  document.querySelectorAll('#flowTop button').forEach(x=>{
    const on=+x.dataset.ft===flowTop;
    x.classList.toggle('on',on);x.setAttribute('aria-pressed',on?'true':'false');});
}
document.querySelectorAll('#flowTop button').forEach(b=>b.onclick=()=>{
  flowTop=+b.dataset.ft;syncFlowTop();refreshStats();
});
// Derived from state rather than stamped into the markup — the pressed button
// and the number of arcs on screen have to be the same fact.
syncFlowTop();
document.getElementById('zfit').onclick=fitView;

/* ---- inspector ---- */
